setPlurality(plurality) {
        switch (plurality) {
            default:
            case CursorPlurality.Single:
                this.j = '';
                break;
            case CursorPlurality.MultiPrimary:
                this.j = 'cursor-primary';
                break;
            case CursorPlurality.MultiSecondary:
                this.j = 'cursor-secondary';
                break;
        }
    }
